// Thin client for the Tezga Fiscal API, generated by hand from the official contract:
// https://tezgafiskal.com/api/openapi.json (v1.6.0). It forwards bodies as-is and does
// not duplicate validation, so it cannot drift from the API. Auth: X-Tezga-Api-Key.

import { TezgaError } from "./errors.js";
import type {
  AdvanceCloseBody,
  AdvanceOpenBody,
  CopyBody,
  Dokument,
  Environment,
  GreskaPolje,
  KalkulacijaBody,
  KupacZapis,
  NivelacijaBody,
  OrderBody,
  Proizvod,
  RefundBody,
  TezgaResponse,
  TransactionsQuery,
} from "./types.js";

export const DEFAULT_BASE_URL = "https://pos.narbiz.com";

export interface TezgaClientOptions {
  /** API key, shape `tzg_` + 48 hex. One key per project; never commit it. */
  apiKey: string;
  /** Override the API host, e.g. to point at a mock server in your own tests. */
  baseUrl?: string;
  /**
   * Tag identifying your integration, sent as `provider`. Defaults to "custom".
   * Max 40 characters.
   */
  provider?: string;
  /** Inject a fetch implementation (tests, older runtimes). Defaults to global fetch. */
  fetch?: typeof fetch;
  /** Abort a request that takes longer than this. Defaults to 30 000 ms. */
  timeoutMs?: number;
}

type Query = Record<string, string | number | undefined>;

export class TezgaClient {
  private readonly apiKey: string;
  private readonly baseUrl: string;
  private readonly provider: string;
  private readonly fetchImpl: typeof fetch;
  private readonly timeoutMs: number;

  constructor(options: TezgaClientOptions) {
    this.apiKey = options.apiKey ?? "";
    this.baseUrl = (options.baseUrl ?? DEFAULT_BASE_URL).replace(/\/$/, "");
    this.provider = options.provider ?? "custom";
    this.fetchImpl = options.fetch ?? globalThis.fetch;
    this.timeoutMs = options.timeoutMs ?? 30_000;
  }

  // ── Receipts ──────────────────────────────────────────────────────────────

  /**
   * Issue and fiscalize a receipt (or a proforma). Idempotent on `externalId`.
   * A 202 means the document was accepted and is still being processed: read
   * `statusDokumenta`, or poll `getDocumentByExternalId`.
   */
  issueReceipt(body: OrderBody): Promise<Dokument> {
    return this.request<Dokument>("POST", "/order", body, { provider: this.provider });
  }

  /** Void ("storno") or refund ("refundacija") a receipt, fully or per item. */
  async refund(body: RefundBody): Promise<Dokument> {
    if (!body.documentId && !body.externalId) {
      throw new TezgaError("Provide documentId or externalId of the original receipt.", 400, null);
    }
    return this.request<Dokument>("POST", "/refund", body);
  }

  /** Issue a copy ("КОПИЈА") of an existing receipt. */
  copyReceipt(body: CopyBody, idempotencyKey?: string): Promise<Dokument> {
    return this.request<Dokument>(
      "POST",
      "/copy",
      body,
      undefined,
      idempotencyKey ? { "Idempotency-Key": idempotencyKey } : undefined,
    );
  }

  // ── Advances ──────────────────────────────────────────────────────────────

  /** Open an advance (avans) receipt for an amount actually received. */
  openAdvance(body: AdvanceOpenBody): Promise<Dokument> {
    return this.request<Dokument>("POST", "/advance", body);
  }

  /** Close an advance: refunds the advance, then issues the final receipt. */
  closeAdvance(body: Omit<AdvanceCloseBody, "zatvori">): Promise<Dokument> {
    return this.request<Dokument>("POST", "/advance", { ...body, zatvori: true });
  }

  // ── Stock and catalogue ───────────────────────────────────────────────────

  /** Costing / goods receipt (kalkulacija). */
  createCosting(body: KalkulacijaBody): Promise<TezgaResponse> {
    return this.request<TezgaResponse>("POST", "/kalkulacija", body);
  }

  /** Price change (nivelacija). */
  createPriceChange(body: NivelacijaBody): Promise<TezgaResponse> {
    return this.request<TezgaResponse>("POST", "/nivelacija", body);
  }

  /** Create or update catalogue items, 1 to 500 per call. */
  upsertProducts(stavke: Proizvod[]): Promise<TezgaResponse> {
    return this.request<TezgaResponse>("POST", "/products", { stavke });
  }

  /** Create or update customers, 1 to 500 per call. */
  upsertCustomers(kupci: KupacZapis[]): Promise<TezgaResponse> {
    return this.request<TezgaResponse>("POST", "/customers", { kupci });
  }

  // ── Reads ─────────────────────────────────────────────────────────────────

  /** Read a document by YOUR order number. */
  getDocumentByExternalId(externalId: string): Promise<Dokument> {
    return this.request<Dokument>("GET", "/documents", undefined, {
      externalId,
      provider: this.provider,
    });
  }

  /** Read a document by its Tezga document ID. */
  getDocument(id: string): Promise<Dokument> {
    return this.request<Dokument>("GET", `/documents/${encodeURIComponent(id)}`);
  }

  /** Tax rates and labels, plus `okruzenje` for this key. */
  getTaxLabels(): Promise<TezgaResponse> {
    return this.request<TezgaResponse>("GET", "/tax-labels");
  }

  /** Bank transactions for the company. */
  getTransactions(query: TransactionsQuery = {}): Promise<TezgaResponse> {
    return this.request<TezgaResponse>("GET", "/transactions", undefined, { ...query });
  }

  /**
   * Environment this key is bound to, as an English enum. Call before issuing:
   * a production key creates a REAL receipt with the Tax Administration.
   */
  async getEnvironment(): Promise<Environment> {
    const labels = await this.getTaxLabels();
    switch (labels?.okruzenje) {
      case "produkcija":
        return "production";
      case "sandbox":
        return "sandbox";
      case "simulacija":
        return "simulation";
      default:
        return "unknown";
    }
  }

  // ── Transport ─────────────────────────────────────────────────────────────

  private async request<T>(
    method: "GET" | "POST",
    path: string,
    body?: unknown,
    query?: Query,
    extraHeaders?: Record<string, string>,
  ): Promise<T> {
    if (!this.apiKey) {
      throw new TezgaError("Missing Tezga API key (shape tzg_...).", 401, null);
    }

    const qs = new URLSearchParams();
    for (const [k, v] of Object.entries(query ?? {})) {
      if (v !== undefined && v !== null && v !== "") qs.set(k, String(v));
    }
    // Build from the string, not URLSearchParams.size, which older runtimes lack.
    const search = qs.toString();
    const url = `${this.baseUrl}/api/integrations${path}${search ? `?${search}` : ""}`;

    let res: Response;
    try {
      res = await this.fetchImpl(url, {
        method,
        headers: {
          "X-Tezga-Api-Key": this.apiKey,
          Accept: "application/json",
          ...(body !== undefined ? { "Content-Type": "application/json" } : {}),
          ...extraHeaders,
        },
        body: body !== undefined ? JSON.stringify(body) : undefined,
        signal: AbortSignal.timeout(this.timeoutMs),
      });
    } catch (err) {
      // Network failure or timeout. Not marked retryable on purpose: re-sending a POST is
      // only safe when the call is idempotent (externalId, or Idempotency-Key on /copy).
      const reason = err instanceof Error ? err.message : String(err);
      throw new TezgaError(`Network error calling Tezga: ${reason}`, 0, null);
    }

    const text = await res.text();
    let data: unknown = text;
    try {
      data = text ? JSON.parse(text) : null;
    } catch {
      // Not every response is JSON; keep the raw text.
    }

    if (!res.ok) {
      let message = `Tezga API ${res.status}`;
      let fields: GreskaPolje[] = [];
      if (data && typeof data === "object") {
        const d = data as { error?: unknown; fields?: unknown };
        if (typeof d.error === "string" && d.error) message = d.error;
        if (Array.isArray(d.fields)) fields = d.fields as GreskaPolje[];
      }
      throw new TezgaError(message, res.status, data, fields);
    }

    return (data ?? {}) as T;
  }
}
